package com.mmpantry.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class AddEditIngredientActivity extends Activity{DatabaseHelper db;EditText name,qty,unit,expiry;int id=-1;public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);id=getIntent().getIntExtra("id",-1);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(36,30,36,20);l.setBackgroundColor(Color.rgb(245,240,232));TextView h=new TextView(this);h.setText(id<0?"Add ingredient":"Edit ingredient");h.setTextSize(28);l.addView(h);name=f("Ingredient name");qty=f("Quantity");unit=f("Unit (pieces, grams, ml)");expiry=f("Expiry date (optional)");l.addView(name);l.addView(qty);l.addView(unit);l.addView(expiry);if(id>=0){Ingredient x=db.getIngredient(id);name.setText(x.name);qty.setText(""+x.quantity);unit.setText(x.unit);expiry.setText(x.expiry);}Button save=new Button(this);save.setText("SAVE TO PANTRY");save.setOnClickListener(v->save());l.addView(save);setContentView(l);}EditText f(String h){EditText e=new EditText(this);e.setHint(h);e.setPadding(0,20,0,20);return e;}void save(){String n=name.getText().toString().trim(),u=unit.getText().toString().trim(),q=qty.getText().toString().trim();if(n.isEmpty()||u.isEmpty()||q.isEmpty()){Toast.makeText(this,"Please complete name, quantity and unit.",Toast.LENGTH_SHORT).show();return;}try{double d=Double.parseDouble(q);if(d<=0)throw new Exception();Ingredient x=new Ingredient(id,n,d,u,expiry.getText().toString().trim());if(id<0)db.insertIngredient(x);else db.updateIngredient(x);finish();}catch(Exception e){Toast.makeText(this,"Quantity must be a positive number.",Toast.LENGTH_SHORT).show();}}}
